import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"FAQ & troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1788283396000}`),a={name:`guide/faq.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="faq-troubleshooting" tabindex="-1">FAQ &amp; troubleshooting <a class="header-anchor" href="#faq-troubleshooting" aria-label="Permalink to “FAQ &amp; troubleshooting”">​</a></h1><h2 id="every-call-comes-back-http-401" tabindex="-1">Every call comes back <code>HTTP 401</code> <a class="header-anchor" href="#every-call-comes-back-http-401" aria-label="Permalink to “Every call comes back HTTP 401”">​</a></h2><p>Almost always the wrong kind of token. This server talks to the <strong>Hetzner Cloud API</strong> (<code>api.hetzner.cloud</code>); tokens created in the old DNS Console (<code>dns.hetzner.com</code>) do not work there, and that API was shut down in May 2026.</p><p>Create a fresh token in the <a href="https://console.hetzner.com" target="_blank" rel="noreferrer">Cloud Console</a> under <strong>your project → Security → API tokens</strong>. If the token is recent and still fails, check that it belongs to the project that actually holds the zones — a token is scoped to one project and sees no zones outside it.</p><h2 id="a-write-comes-back-http-403" tabindex="-1">A write comes back <code>HTTP 403</code> <a class="header-anchor" href="#a-write-comes-back-http-403" aria-label="Permalink to “A write comes back HTTP 403”">​</a></h2><p>The token is read-only. Generate a <strong>Read &amp; Write</strong> token, or keep the read-only one and set <code>HETZNER_READ_ONLY=true</code> so the write tools stop being offered at all.</p><h2 id="a-call-comes-back-http-423" tabindex="-1">A call comes back <code>HTTP 423</code> <a class="header-anchor" href="#a-call-comes-back-http-423" aria-label="Permalink to “A call comes back HTTP 423”">​</a></h2><p>The resource is protected on Hetzner&#39;s side. Remove the protection with <code>change_zone_protection</code> or <code>change_rrset_protection</code> — which itself needs a confirmation token, because removing protection is treated as destructive — and then retry.</p><h2 id="a-dialog-appeared-before-my-deletion" tabindex="-1">A dialog appeared before my deletion <a class="header-anchor" href="#a-dialog-appeared-before-my-deletion" aria-label="Permalink to “A dialog appeared before my deletion”">​</a></h2><p>That is the <a href="/guide/approval">approval flow</a> working. Where your client supports MCP elicitation, anything irreversible raises a question the model cannot answer on its behalf, and nothing happens until you answer it.</p><h2 id="the-server-keeps-refusing-my-deletion-with-a-confirm-token" tabindex="-1">The server keeps refusing my deletion, with a <code>confirm_token</code> <a class="header-anchor" href="#the-server-keeps-refusing-my-deletion-with-a-confirm-token" aria-label="Permalink to “The server keeps refusing my deletion, with a confirm_token”">​</a></h2><p>That is the <strong>fallback</strong>, for a client that cannot show a dialog. It was once the only path; it is not any more. The first call returns a <code>confirm_token</code>, and the second must repeat the <strong>identical arguments</strong> and include it.</p><p>If your client <em>can</em> show dialogs and you are still seeing tokens, check whether <code>ELICITATION</code> is set to <code>false</code> somewhere in the environment — it deliberately carries no <code>HETZNER_</code> prefix, so it may have been meant for a different server. The startup log of this one says so when it is off.</p><p>If the second call is refused too, one of these is true:</p><ul><li>More than five minutes passed. Tokens expire; call again for a fresh one.</li><li>The arguments changed. For <code>set_records</code>, <code>remove_records</code>, <code>import_zonefile</code> and <code>change_primary_nameservers</code> the token is bound to a hash of the payload — even a reordered record list is a different payload.</li><li>The token was already used. They are single-use.</li><li>The server restarted. Tokens live in memory only.</li></ul><h2 id="missing-required-environment-variable-hetzner-api-token" tabindex="-1"><code>missing required environment variable HETZNER_API_TOKEN</code> <a class="header-anchor" href="#missing-required-environment-variable-hetzner-api-token" aria-label="Permalink to “missing required environment variable HETZNER_API_TOKEN”">​</a></h2><p>The variable never reached the process. Client configurations set it in different places:</p><ul><li>Claude Code — <code>-e HETZNER_API_TOKEN=…</code> on <code>claude mcp add</code></li><li>Claude Desktop / Codex — the <code>env</code> block of the server entry</li><li>Docker — <code>-e HETZNER_API_TOKEN</code> <strong>and</strong> the variable present in the client&#39;s <code>env</code> block</li></ul><p>Note that the server intentionally still starts and lists all its tools without a token, so &quot;the tools are there&quot; is not evidence that the token arrived.</p><h2 id="the-tools-do-not-show-up-at-all" tabindex="-1">The tools do not show up at all <a class="header-anchor" href="#the-tools-do-not-show-up-at-all" aria-label="Permalink to “The tools do not show up at all”">​</a></h2><p>The client could not start the command. Check its MCP log. Common causes: no Node ≥ 22 on <code>PATH</code>, <code>npx</code> blocked by a corporate proxy, or a typo in the command. Try running the same command by hand — it should print a line to stderr and then wait silently for JSON-RPC on stdin.</p><h2 id="one-tool-i-expected-is-missing" tabindex="-1">One tool I expected is missing <a class="header-anchor" href="#one-tool-i-expected-is-missing" aria-label="Permalink to “One tool I expected is missing”">​</a></h2><p>Something narrowed the list. In order of likelihood:</p><ul><li><code>HETZNER_READ_ONLY</code> is set, and it is a write tool. <code>tools/list</code> returns seven.</li><li><code>HETZNER_ALLOW_TOOLS</code> is set and does not name it — remember that it is an allow list, so anything not named is out.</li><li><code>HETZNER_DENY_TOOLS</code> names it, possibly through a prefix such as <code>delete_*</code>.</li></ul><p>A filtered tool is not registered at all, so it is missing from <code>tools/list</code> and answers <code>tools/call</code> with &quot;tool not found&quot; — the same as a write tool under read-only. There is no state where it is hidden but still callable.</p><p>What it is <em>not</em> is a typo in one of those variables: an entry that matches no tool stops the server at startup and says which entry it was. See <a href="/guide/configuration#choosing-the-tools-that-load">choosing the tools that load</a>.</p><h2 id="can-i-stop-it-from-changing-anything" tabindex="-1">Can I stop it from changing anything? <a class="header-anchor" href="#can-i-stop-it-from-changing-anything" aria-label="Permalink to “Can I stop it from changing anything?”">​</a></h2><p>Yes, two independent ways, best used together:</p><div class="language-json"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;env&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: {</span></span>
<span class="line"><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">  &quot;HETZNER_API_TOKEN&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;a-read-only-token&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">,</span></span>
<span class="line"><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">  &quot;HETZNER_READ_ONLY&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;true&quot;</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">}</span></span></code></pre></div><p>Read-only mode never registers the write tools, and a read-only token means the API would refuse them anyway. See <a href="/guide/configuration#read-only-mode">Configuration</a>.</p><p>To cut further than &quot;no writes&quot; — say, five tools rather than seven — add <code>HETZNER_ALLOW_TOOLS</code>; the two combine.</p><h2 id="why-is-a-result-wrapped-in-untrusted-data" tabindex="-1">Why is a result wrapped in <code>&lt;untrusted-data&gt;</code>? <a class="header-anchor" href="#why-is-a-result-wrapped-in-untrusted-data" aria-label="Permalink to “Why is a result wrapped in &lt;untrusted-data&gt;?”">​</a></h2><p>Because record values, comments, labels and zone files are written by whoever controls the zone, which is not necessarily you — think of a secondary zone transferred from an external primary. The envelope tells the model to treat that content as data to report, not instructions to follow. See <a href="/guide/security#untrusted-upstream-data">Security</a>.</p><h2 id="a-result-says-it-was-truncated" tabindex="-1">A result says it was truncated <a class="header-anchor" href="#a-result-says-it-was-truncated" aria-label="Permalink to “A result says it was truncated”">​</a></h2><p>Single values are capped at 4 000 characters and a whole result at 200 000, so one large zone cannot fill the context window. Narrow the query instead of retrying: <code>per_page</code> and <code>page</code> on the list tools, or <code>get_rrset</code> for a single record set. For a full zone dump, <code>export_zonefile</code> returns the zone file, but very large zones will still be cut.</p><h2 id="does-it-support-the-old-dns-api" tabindex="-1">Does it support the old DNS API? <a class="header-anchor" href="#does-it-support-the-old-dns-api" aria-label="Permalink to “Does it support the old DNS API?”">​</a></h2><p>No, and it will not. <code>dns.hetzner.com</code> was shut down in May 2026. If you have scripts still using it, they are already broken for reasons unrelated to this server.</p><h2 id="can-i-run-it-against-something-other-than-hetzner" tabindex="-1">Can I run it against something other than Hetzner? <a class="header-anchor" href="#can-i-run-it-against-something-other-than-hetzner" aria-label="Permalink to “Can I run it against something other than Hetzner?”">​</a></h2><p><code>HETZNER_API_BASE_URL</code> exists for pointing at a local mock during development. It is validated (https only, no credentials in the URL, warning on a non-default host) precisely because your token gets sent there. It is not a way to use this against a different DNS provider — the request shapes are Hetzner&#39;s.</p><h2 id="where-do-i-report-a-bug" tabindex="-1">Where do I report a bug? <a class="header-anchor" href="#where-do-i-report-a-bug" aria-label="Permalink to “Where do I report a bug?”">​</a></h2><p><a href="https://github.com/ni-c/hetzner-dns-mcp/issues" target="_blank" rel="noreferrer">Issues</a> for reproducible problems, <a href="https://github.com/ni-c/hetzner-dns-mcp/discussions" target="_blank" rel="noreferrer">Discussions</a> for questions, and <a href="https://github.com/ni-c/hetzner-dns-mcp/security/advisories/new" target="_blank" rel="noreferrer">private reporting</a> for anything security-related. Please redact tokens, real zone names and records — issues are public.</p>`,41)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};